import { MorphEngine } from '@magic-spells/morph-engine';

// Capture-at-click album-art flight — the sibling-view case the router morph can't do.
//
// enableMorph (D55) pairs `data-puzzle-morph` elements ACROSS a route swap, but only
// when both live in the same mounted subtree at some point — it works for the Artist
// "Info" overlay because that's a CHILD route (the source button stays mounted). It
// cannot bridge a SIBLING view swap: Puzzle's route transitions are sequential, so
// clicking an AlbumCard destroys the Library/Artist view (and its card) BEFORE the
// Album view mounts. There is no moment where both the card art and the header art
// are in the DOM for the router to pair.
//
// So we bridge it app-side: at click time, clone the card artwork into a
// position:fixed stand-in on <body> (survives the source view's teardown), then when
// the Album view's real header artwork appears — a beat later, at the skeleton→real
// swap — fly the clone into it with a dedicated MorphEngine's spring physics.
//
// Scope: FORWARD direction only. A back-navigation has no click to capture, so the
// return trip is deferred. Framework-free by design — no @magic-spells/puzzle imports.

// One engine + one in-progress capture for the whole module. Spring tuning matches
// the router integration / QueueDialog (the engine's own defaults settle floatier).
let engine = null;
let pending = null; // { id, clone, observer, ttlTimer }

function getEngine() {
	if (!engine) engine = new MorphEngine({ attraction: 0.1, friction: 0.32, zIndex: 60 });
	return engine;
}

// Tear down whatever capture is in flight: drop its clone, disconnect its observer,
// clear its TTL. Does NOT touch the engine — the caller decides that.
function cancelPending() {
	if (!pending) return;
	if (pending.observer) pending.observer.disconnect();
	if (pending.ttlTimer) clearTimeout(pending.ttlTimer);
	if (pending.clone && pending.clone.isConnected) pending.clone.remove();
	pending = null;
}

export function captureArtMorph(artworkEl, morphId) {
	// Respect reduced-motion; bail if there's nothing measurable to fly.
	if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
	if (!artworkEl || artworkEl.getClientRects().length === 0) return;

	// Supersede any previous capture and abort a morph still in flight.
	cancelPending();
	const eng = getEngine();
	if (eng.state !== 'idle') eng.stop();

	// Clone the artwork into a fixed stand-in pinned over the original card. While the
	// old view fades out the art appears to hold still — that's the effect, not a bug.
	const rect = artworkEl.getBoundingClientRect();
	const clone = artworkEl.cloneNode(true);
	// CRITICAL: the clone must never match the observer selector or any counterpart scan.
	clone.removeAttribute('data-art-morph');
	// Explicit width/height beat the aspect-square utility; z below the engine's blob (60).
	clone.style.cssText =
		`position:fixed; top:${rect.top}px; left:${rect.left}px; width:${rect.width}px; ` +
		`height:${rect.height}px; margin:0; z-index:55; pointer-events:none;`;
	document.body.appendChild(clone);

	const record = { id: morphId, clone, observer: null, ttlTimer: null };
	pending = record;
	const selector = `[data-art-morph="${CSS.escape(morphId)}"]`;

	// Fly clone → target, then unwind to a clean idle engine for the next capture.
	const fly = async (target) => {
		if (record.observer) { record.observer.disconnect(); record.observer = null; }
		if (record.ttlTimer) { clearTimeout(record.ttlTimer); record.ttlTimer = null; }

		const settled = await eng.show({ from: clone, to: target });

		// One-shot: always drop the clone (target is gone or not, connected or not).
		if (clone.isConnected) clone.remove();
		// Only tidy the engine when WE actually landed. A `false` here means a newer
		// capture superseded us (its stop() resolved this promise) and may already own
		// a fresh flight — calling stop() then would abort ITS morph. finalizeShown
		// leaves the target visible with no inline residue; stop() at 'shown' just
		// clears the shown flag and unlocks scroll, so it never flashes the target.
		if (settled && eng.state !== 'idle') eng.stop();
		if (pending === record) pending = null;
	};

	// Immediate check: reusable for a same-tree pairing (won't hit for a sibling swap).
	const existing = document.querySelector(selector);
	if (existing && existing !== artworkEl && existing.getClientRects().length > 0) {
		fly(existing);
		return;
	}

	// Watch for the target appearing (Album view mount → skeleton→real artwork swap).
	const observer = new MutationObserver(() => {
		const target = document.querySelector(selector);
		if (target && target.getClientRects().length > 0) fly(target);
	});
	observer.observe(document.body, { childList: true, subtree: true });
	record.observer = observer;

	// TTL: no target within 2s (failed nav, wrong route, not-found) → fade + drop the
	// clone. It's pointer-events:none, so a stale one can never block clicks meanwhile.
	record.ttlTimer = setTimeout(() => {
		if (record.observer) { record.observer.disconnect(); record.observer = null; }
		record.ttlTimer = null;
		clone.style.transition = 'opacity 150ms';
		clone.style.opacity = '0';
		setTimeout(() => { if (clone.isConnected) clone.remove(); }, 150);
		if (pending === record) pending = null;
	}, 2000);
}
