/**
 * Shared-element morph route transitions (v1.23, D55) — the puzzle-owned
 * convention over @magic-spells/morph-engine.
 *
 * Mark any two elements with the same `data-puzzle-morph` value and the router
 * morphs between them whenever a navigation swaps one of them in or out: a
 * spring-driven blob grows from the surviving element (a task card) into the
 * freshly mounted one (its detail dialog), and flies back when the dialog's
 * route leaves — including via the browser back button, which runs the same
 * pipeline. One line activates it:
 *
 *   import { enableMorph } from '@magic-spells/puzzle/morph';
 *   enableMorph(app);
 *
 * Pairing is identity-based (the view-transition-name / layoutId model): the
 * shared attribute VALUE says "same logical surface"; the navigation direction
 * says which way to fly. The initial navigation never morphs — deep links show
 * the view plainly — and `prefers-reduced-motion` disables morphing entirely.
 *
 * This module is the whole integration: the router only exposes the narrow
 * setMorphHandler slot (enter after a committed swap mounts, pre-paint; leave
 * awaited before an outgoing unit is destroyed). Everything morph-shaped —
 * scanning, pairing, guards, engine lifecycle — lives here, so apps that never
 * import this subpath bundle none of it (the engine is an optional peer dep).
 *
 * Rules for morph elements (see the engine's own docs for the full list):
 * - No transform-based positioning and no stylesheet `opacity` on the target —
 *   the engine drives inline transform/opacity during the reveal. Center with
 *   flex or `inset: 0; margin: auto`.
 * - No CHANGING dynamic `style={}` binding on either element — the patcher
 *   rewrites the whole style attribute and would clobber the engine's frames.
 * - Route-mounted targets need no resting `visibility: hidden` — the engine
 *   hides both elements synchronously at show(), before the browser paints.
 */

import { MorphEngine } from '@magic-spells/morph-engine';

const ATTRIBUTE = 'data-puzzle-morph';

/**
 * Create a MorphEngine and register it as the app router's morph handler.
 * Call once, after `new PuzzleApp(...)` — before or after mount() both work
 * (the handler is only consulted during swaps).
 *
 * @param {import('./app.js').PuzzleApp} app
 * @param {object} [options] MorphEngine options (attraction, friction,
 *   revealAt, zIndex, ...) plus `attribute` to override the pairing attribute.
 * @returns {MorphEngine} the engine, for live tuning and events
 */
export function enableMorph(app, options = {}) {
	const { attribute = ATTRIBUTE, ...engineOptions } = options;
	const engine = new MorphEngine({ attraction: 0.1, friction: 0.32, ...engineOptions });

	// The currently shown (or in-flight) pairing. `id` is the attribute value at
	// show() time — a later params-only navigation can re-point the same mounted
	// view at new content, which changes the attribute WITHOUT a swap; leave()
	// compares against this to refuse flying back to the wrong counterpart.
	let pair = null;

	const reducedMotion = () =>
		typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

	/** First element carrying `id` that is outside `excludeRoot` and measurable. */
	const findCounterpart = (id, excludeRoot) => {
		for (const candidate of document.querySelectorAll(`[${attribute}]`)) {
			if (
				candidate.getAttribute(attribute) === id &&
				!excludeRoot.contains(candidate) &&
				candidate.getClientRects().length > 0
			) {
				return candidate;
			}
		}
		return null;
	};

	app.setMorphHandler({
		enter(el, { initial }) {
			// An interrupted transition (skipped out phase, abandoned commit) can
			// strand a run — every enter starts from a clean engine no matter what.
			if (engine.state !== 'idle') engine.stop();
			pair = null;

			if (initial || !el || el.nodeType !== 1 || reducedMotion()) return;
			const target = el.matches(`[${attribute}]`) ? el : el.querySelector(`[${attribute}]`);
			const id = target?.getAttribute(attribute);
			if (!id) return;
			const source = findCounterpart(id, el);
			if (!source) return;

			pair = { id, source, target };
			engine.show({ from: source, to: target });
		},

		leave(el) {
			if (!pair || !el || el.nodeType !== 1) return null;
			const { id, source, target } = pair;
			pair = null;

			// Fly back only when the round trip is intact: the leaving subtree holds
			// our target, the target still shows the id we paired on (params-only
			// task switches change it in place), and the source survives OUTSIDE the
			// leaving subtree (a whole-chain teardown takes the card with it — an
			// instant close, not a morph into a dying element). Anything off →
			// stop(): both elements restore to their resting state immediately.
			const intact =
				engine.state !== 'idle' &&
				el.contains(target) &&
				target.getAttribute(attribute) === id &&
				source.isConnected &&
				!el.contains(source) &&
				!reducedMotion();
			if (!intact) {
				engine.stop();
				return null;
			}
			return engine.hide();
		},
	});

	return engine;
}
